    # Show bounding box
    rows = [r for r, c in positions]
    cols = [c for r, c in positions]
    print(f"  Bounding box: rows {min(rows)}-{max(rows)}, cols {min(cols)}-{max(cols)}")

# Let me try another hypothesis - extract only non-5 parts from each quadrant
# This preserves the pattern structure but removes background (5s)

def get_non_5_quadrants(n, m, block_size=6):
    result = []
    for r_start in range(0, n, block_size):
        for c_start in range(0, m, block_size):
            br = min(n, r_start + block_size)
            bc = min(m, c_start + block_size)

            # Extract non-5 values with their positions relative to quadrant
            non_5_positions = []
            for r in range(r_start, br):
                for c in range(c_start, bc):
                    if grid[r][c] != 5:
                        non_5_positions.append((r - r_start, c - c_start, grid[r][c]))

            result.append(non_5_positions)
    return result

quadrants = get_non_5_quadrants(len(grid), len(grid[0]))

for i, q in enumerate(quadrants):
    print(f"\nQuadrant {i}: {len(q)} non-5 cells")
    for pos, val in q:
        print(f"  ({pos[0]}, {pos[1]}): {val}")

